-- Cahaya Kuphi initial schema. Run in Supabase SQL Editor after reviewing.
create extension if not exists pgcrypto;
create table if not exists public.categories (id text primary key, name_id text not null, name_en text not null, sort_order int not null default 0, is_active boolean not null default true);
create table if not exists public.products (id text primary key, category_id text references public.categories(id), name_id text not null, name_en text not null, description_id text not null default '', description_en text not null default '', base_price integer not null check(base_price>=0), photo_url text, is_active boolean not null default true, inventory_mode text not null default 'shared' check(inventory_mode in ('shared','variant')), stock_quantity integer check(stock_quantity is null or stock_quantity>=0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.product_variants (id uuid primary key default gen_random_uuid(), product_id text not null references public.products(id) on delete cascade, name_id text not null, name_en text not null, is_required boolean not null default true, sort_order int not null default 0);
create table if not exists public.variant_options (id uuid primary key default gen_random_uuid(), variant_id uuid not null references public.product_variants(id) on delete cascade, label_id text not null, label_en text not null, price_delta integer not null default 0 check(price_delta>=0), stock_quantity integer check(stock_quantity is null or stock_quantity>=0), is_active boolean not null default true, sort_order int not null default 0);
create table if not exists public.product_extras (id uuid primary key default gen_random_uuid(), product_id text not null references public.products(id) on delete cascade, name_id text not null, name_en text not null, is_required boolean not null default false, sort_order int not null default 0);
create table if not exists public.product_extra_options (id uuid primary key default gen_random_uuid(), extra_id uuid not null references public.product_extras(id) on delete cascade, label_id text not null, label_en text not null, price_delta integer not null default 0 check(price_delta>=0), is_active boolean not null default true);
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_code text not null unique, customer_name text not null, customer_phone text not null, fulfillment_mode text not null check(fulfillment_mode in ('delivery','pickup')), delivery_address text, landmark text, customer_notes text not null default '', subtotal integer not null check(subtotal>=0), delivery_fee integer not null default 0 check(delivery_fee>=0), total_amount integer not null check(total_amount>=0), order_status text not null default 'pending_confirmation' check(order_status in ('pending_confirmation','confirmed','processing','ready_for_pickup','out_for_delivery','completed','cancelled','expired')), payment_method text not null default 'cash' check(payment_method in ('cash','transfer','qris')), payment_status text not null default 'unpaid' check(payment_status in ('unpaid','awaiting_verification','paid','failed')), tracking_token_hash text not null, expires_at timestamptz not null, confirmed_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id text references public.products(id) on delete set null, product_name_id text not null, product_name_en text not null, unit_price integer not null check(unit_price>=0), quantity integer not null check(quantity between 1 and 50), line_total integer not null check(line_total>=0), selected_options jsonb not null default '[]'::jsonb);
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, method text not null, amount integer not null check(amount>=0), verification_status text not null default 'unpaid' check(verification_status in ('unpaid','awaiting_verification','verified','rejected')), reference text, verified_by uuid, verified_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.stock_movements (id uuid primary key default gen_random_uuid(), product_id text references public.products(id) on delete set null, variant_option_id uuid references public.variant_options(id) on delete set null, order_id uuid references public.orders(id) on delete set null, movement_type text not null check(movement_type in ('restock','order_confirmed','order_cancelled','adjustment')), quantity_delta integer not null, note text not null default '', created_at timestamptz not null default now());
create table if not exists public.store_settings (id integer primary key default 1 check(id=1), store_name text not null default 'Cahaya Kuphi Resto & Cafe', whatsapp_admin text, cafe_address text, delivery_fee integer check(delivery_fee is null or delivery_fee>=0), accepting_orders boolean not null default false, payment_instructions_id text not null default '', payment_instructions_en text not null default '', qris_image_url text, updated_at timestamptz not null default now());
create table if not exists public.store_hours (id uuid primary key default gen_random_uuid(), weekday smallint not null check(weekday between 0 and 6), is_open boolean not null default false, opens_at time, closes_at time, unique(weekday));
insert into public.categories(id,name_id,name_en,sort_order) values ('kopi','Kopi','Coffee',1),('teh','Teh','Tea',2),('jus','Jus','Juice',3),('squash','Squash','Squash',4),('makanan','Makanan','Meals',5),('camilan','Camilan','Snacks',6) on conflict(id) do nothing;
insert into public.products(id,category_id,name_id,name_en,description_id,description_en,base_price,is_active,stock_quantity) values ('kopi-sanger','kopi','Kopi Sanger','Sanger Coffee','Kopi espresso dengan perpaduan susu yang lembut dan rasa kopi yang seimbang.','Espresso blended with smooth milk for a balanced coffee flavour.',18000,true,50),('americano','kopi','Americano','Americano','Kopi hitam dengan karakter rasa yang bersih dan menyegarkan.','Clean, refreshing black coffee with a bold character.',16000,true,50),('lemon-tea','teh','Lemon Tea','Lemon Tea','Teh dengan sentuhan lemon yang segar.','Refreshing tea with a bright hint of lemon.',12000,true,50),('jus-alpukat','jus','Jus Alpukat','Avocado Juice','Jus alpukat lembut dengan rasa creamy.','Creamy avocado juice with a rich, smooth taste.',18000,true,30),('ayam-penyet','makanan','Ayam Penyet','Smashed Fried Chicken','Ayam goreng dengan sambal dan pelengkap.','Fried chicken served with sambal and accompaniments.',25000,true,30),('nasi-goreng-kampung','makanan','Nasi Goreng Kampung','Village-Style Fried Rice','Nasi goreng berbumbu khas.','Seasoned fried rice with a savoury flavour.',22000,true,30),('kentang-goreng','camilan','Kentang Goreng','French Fries','Kentang goreng renyah.','Crispy fries, a perfect snack.',15000,true,30),('strawberry-squash','squash','Strawberry Squash','Strawberry Squash','Minuman soda rasa stroberi yang menyegarkan.','A fizzy strawberry drink that is refreshing.',16000,true,30) on conflict(id) do nothing;
-- Security defaults: deny public table access. Configure RLS policies only after defining the admin role and public read requirements.
alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_variants enable row level security; alter table public.variant_options enable row level security; alter table public.product_extras enable row level security; alter table public.product_extra_options enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.stock_movements enable row level security; alter table public.store_settings enable row level security; alter table public.store_hours enable row level security;
-- Do not add broad public INSERT/UPDATE policies to orders, stock, or settings. API routes currently use server-only service role. Add tested admin-only policies before building production admin CRUD.
